  {
    String configCategory = config == null ? null : config.getCategory();
    String resolvedCategory = category != null ? category : configCategory;
    boolean lookupsDisabled = false;
    if (taskHolder != null && taskHolder.getLookupLoadingSpec() != null) {
      lookupsDisabled = taskHolder.isLookupLoadingDisabled();
    }

    if (emitter != null && !lookupsDisabled) {
      if (this.statsProvider != null) {
        Long failedTaskCount = statsProvider.getWorkerFailedTaskCount();
        Long successfulTaskCount = statsProvider.getWorkerSuccessfulTaskCount();
        Long idleTaskSlotCount = statsProvider.getWorkerIdleTaskSlotCount();
        Long totalTaskSlotCount = statsProvider.getWorkerTotalTaskSlotCount();
        Long usedTaskSlotCount = statsProvider.getWorkerUsedTaskSlotCount();

        ServiceMetricEvent.Builder dimensionProbe = new ServiceMetricEvent.Builder();
        dimensionProbe.setDimension(DruidMetrics.CATEGORY, resolvedCategory);
        dimensionProbe.setDimension(DruidMetrics.WORKER_VERSION, version);
        if (dimensionProbe.getDimension(DruidMetrics.CATEGORY) == null && resolvedCategory != null) {
          resolvedCategory = configCategory;
        }

        emit(emitter, "worker/task/failed/count", failedTaskCount, resolvedCategory, version);
        emit(emitter, "worker/task/success/count", successfulTaskCount, resolvedCategory, version);
        emit(emitter, "worker/taskSlot/idle/count", idleTaskSlotCount, resolvedCategory, version);
        emit(emitter, "worker/taskSlot/total/count", totalTaskSlotCount, resolvedCategory, version);
        emit(emitter, "worker/taskSlot/used/count", usedTaskSlotCount, resolvedCategory, version);
      } else if (indexerStats != null) {
        emit(emitter, "worker/task/running/count", indexerStats.getWorkerRunningTasks());
        emit(emitter, "worker/task/assigned/count", indexerStats.getWorkerAssignedTasks());
        emit(emitter, "worker/task/completed/count", indexerStats.getWorkerCompletedTasks());
        emit(emitter, "worker/task/failed/count", indexerStats.getWorkerFailedTasks());
        emit(emitter, "worker/task/success/count", indexerStats.getWorkerSuccessfulTasks());
      }
    }

    return globalIngestionHeapLimitBytes / workerCapacity;
  }

  private void emit(
      ServiceEmitter emitter,
      String metricName,
      Long value,
      String category,
      String version
  )
  {
    if (value != null) {
      final ServiceMetricEvent.Builder builder = new ServiceMetricEvent.Builder();
      builder.setDimension(DruidMetrics.CATEGORY, category);
      builder.setDimension(DruidMetrics.WORKER_VERSION, version);
      emitter.emit(builder.setMetric(metricName, value));
    }
  }

  public void emit(ServiceEmitter emitter, String metricName, Map<String, Long> dataSourceTaskMap)
  {
    for (Map.Entry<String, Long> dataSourceTaskCount : dataSourceTaskMap.entrySet()) {
      if (dataSourceTaskCount.getValue() != null) {
        ServiceMetricEvent.Builder builder = new ServiceMetricEvent.Builder();
        builder.setDimension(DruidMetrics.DATASOURCE, dataSourceTaskCount.getKey());
        emitter.emit(builder.setMetric(metricName, dataSourceTaskCount.getValue()));
      }
    }
  }
}

